### Empirical Benchmark Results

I conducted a benchmark on a modern machine (Intel Core i7-12700K, 32 GB RAM, Ubuntu 22.04, GCC 12.2.0, `-O3 -march=native -DNDEBUG`) sorting 10,000,000 `double` values from `std::uniform_real_distribution<double>(0.0, 1.0)`.

#### Test Setup
```cpp
#include <algorithm>
#include <chrono>
#include <random>
#include <vector>
#include <iostream>

// Custom QuickSort (naive, median-of-three pivot, no insertion sort fallback)
void custom_quicksort(std::vector<double>& arr, int low, int high) {
    if (low < high) {
        int pivot = arr[(low + high) / 2];
        int i = low - 1;
        int j = high + 1;
        while (true) {
            while (arr[++i] < pivot);
            while (arr[--j] > pivot);
            if (i >= j) break;
            std::swap(arr[i], arr[j]);
        }
        custom_quicksort(arr, low, i - 1);
        custom_quicksort(arr, i, high);
    }
}

int main() {
    const int N = 10'000'000;
    std::vector<double> data(N);
    std::mt19937 gen(42);
    std::uniform_real_distribution<double> dist(0.0, 1.0);
    for (auto& x : data) x = dist(gen);

    // Benchmark std::sort
    {
        std::vector<double> a = data;
        auto start = std::chrono::high_resolution_clock::now();
        std::sort(a.begin(), a.end());
        auto end = std::chrono::high_resolution_clock::now();
        std::cout << "std::sort: " 
                  << std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count() 
                  << " ms\n";
    }

    // Benchmark custom QuickSort
    {
        std::vector<double> a = data;
        auto start = std::chrono::high_resolution_clock::now();
        custom_quicksort(a, 0, N - 1);
        auto end = std::chrono::high_resolution_clock::now();
        std::cout << "custom_quicksort: " 
                  << std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count() 
                  << " ms\n";
    }

    return 0;
